#pragma once
#include <NexumDesign.h>
#include "Processor.h"
namespace noctrl {
// Twelve chromatic keys select the twelve existing sequence slots.
class SequenceMiniKeyboard:public juce::Component,public juce::SettableTooltipClient {
 SynthProcessor& p;bool arp;int copyFrom=-1;static constexpr int headerHeight=22;
 juce::Colour accent()const{return nd::colour(juce::Colour(arp?0xffbc84ff:0xff51d5ac));}
 bool populated(int slot)const{auto bank=p.sequences();return arp||!bank->clips[slot].notes.empty()||!bank->clips[slot].lanes.empty();}
public:
 std::function<void()> onEdit;
 SequenceMiniKeyboard(SynthProcessor& processor,bool isArp):p(processor),arp(isArp){setComponentID(arp?"arp-mini-keyboard":"clip-mini-keyboard");setTitle(arp?"Arpeggiator pattern keyboard":"Clip launch keyboard");setDescription("Twelve keys select sequence slots. Power at top left; title opens the editor.");setWantsKeyboardFocus(true);setMouseCursor(juce::MouseCursor::PointingHandCursor);setTooltip(arp?"ARP: click a key to select and enable a pattern. Shift-click selects only. Click the title to edit.":"CLIP: click a populated key to launch/stop. Shift-click selects only. Click the title to edit.");}
 bool isEnabledForPlayback()const{return arp?p.sequenceArpEnabled():p.value("seqClipEnabled")>.5f;}
 juce::Rectangle<float> slotBounds(int slot)const{float white=getWidth()/7.f,top=headerHeight+2.f,height=juce::jmax(1.f,getHeight()-top-2);const int whites[]={0,2,4,5,7,9,11};for(int i=0;i<7;++i)if(whites[i]==slot)return {i*white,top,white-1,height};const int blacks[]={1,3,6,8,10},boundaries[]={1,2,4,5,6};for(int i=0;i<5;++i)if(blacks[i]==slot)return {boundaries[i]*white-white*.29f,top,white*.58f,height*.63f};return {};}
 int slotAt(juce::Point<float> point)const{if(point.y<headerHeight)return -1;for(int slot:{1,3,6,8,10})if(slotBounds(slot).contains(point))return slot;for(int slot:{0,2,4,5,7,9,11})if(slotBounds(slot).contains(point))return slot;return -1;}
 void togglePlayback(){if(arp)p.setSequenceArpEnabled(!p.sequenceArpEnabled());else p.set("seqClipEnabled",1-p.value("seqClipEnabled"));repaint();}
 void selectSlot(int slot,bool selectionOnly=false){if(slot<0||slot>=12)return;p.set(arp?"seqArpSlot":"seqClipSlot",(float)slot);if(!selectionOnly){if(arp)p.setSequenceArpEnabled(true);else if(populated(slot)){p.set("seqClipEnabled",1);p.clipRequest.store(slot);}}repaint();}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("keyboard");using namespace juce;auto r=getLocalBounds().toFloat();g.setColour(nd::colour(nd::colour(Colour(0xff0c1620))));g.fillRoundedRectangle(r,nd::number("radius",4));Path header;header.addRoundedRectangle(0,0,r.getWidth(),headerHeight,nd::number("radius",4),nd::number("radius",4),true,true,false,false);g.setColour(nd::colour(nd::colour(Colour(0xff243442))));g.fillPath(header);bool enabled=isEnabledForPlayback();auto colour=accent();g.setColour(nd::colour(enabled?colour:Colour(0xff6c8190)));Path power;power.addCentredArc(10,11,4.5f,4.5f,0,.65f,MathConstants<float>::twoPi-.65f,true);g.strokePath(power,PathStrokeType(nd::number("stroke",1.4f)));g.drawLine(10,5,10,10,1.5f);g.setFont(FontOptions(nd::number("fontSize",10.5f),Font::bold));g.drawText(arp?"ARP":"CLIP",Rectangle<int>(22,0,getWidth()-25,headerHeight),Justification::centredLeft,false);int selected=juce::jlimit(0,11,(int)p.value(arp?"seqArpSlot":"seqClipSlot")),playing=p.clipPlayingMask.load(),queued=p.clipQueuedMask.load();auto draw=[&](int slot,bool black){auto key=slotBounds(slot);bool active=enabled&&(arp?slot==p.arpPlayingSlot.load():(playing&(1<<slot))!=0);bool pending=arp?p.arpQueuedSlot.load()==slot:(queued&(1<<slot));Colour base=nd::colour(Colour(black?0xff101a23:0xff263540));if(active)base=base.interpolatedWith(colour,.65f);else if(pending)base=base.interpolatedWith(nd::colour(Colour(0xffffc568)),.4f);g.setGradientFill(ColourGradient(base.brighter(.08f),key.getCentreX(),key.getY(),base.darker(.16f),key.getCentreX(),key.getBottom(),false));g.fillRect(key);g.setColour(nd::colour(nd::colour(Colour(0xff080e14))));g.drawRect(key,.7f);if(slot==selected){g.setColour(nd::colour(colour.withAlpha(enabled?.95f:.4f)));g.drawRect(key.reduced(.7f),1.f);}if(populated(slot)){g.setColour(nd::colour(active?colour:colour.withAlpha(.3f)));g.fillRect(key.getX()+1,key.getY()+1,juce::jmax(1.f,key.getWidth()-2),2.f);}if(active&&!arp){float progress=juce::jlimit(0.f,1.f,p.clipSlotProgress[slot].load());g.setColour(nd::colour(colour));g.fillRect(key.getX()+1,key.getBottom()-3,juce::jmax(0.f,(key.getWidth()-2)*progress),2.f);}};for(int slot:{0,2,4,5,7,9,11})draw(slot,false);for(int slot:{1,3,6,8,10})draw(slot,true);if(arp&&enabled){bool sounding=false;for(auto& note:p.generatedNotes)sounding|=note.load()>0;g.setColour(nd::colour(colour.withAlpha(sounding?1.f:.2f)));g.fillRect(getWidth()-3,headerHeight+2,2,juce::jmax(1,getHeight()-headerHeight-4));}g.setColour(nd::colour(nd::colour(Colour(0xff344650))));g.drawRoundedRectangle(r.reduced(.5f),nd::number("radius",3.5f),.7f);}
 void mouseDown(const juce::MouseEvent& e)override{if(e.position.y<headerHeight){if(e.mods.isPopupMenu())return;if(e.position.x<20)togglePlayback();else if(onEdit)onEdit();return;}int slot=slotAt(e.position);if(slot<0)return;if(e.mods.isAltDown()&&!e.mods.isPopupMenu()){copyFrom=slot;return;}selectSlot(slot,e.mods.isShiftDown()||e.mods.isPopupMenu());if(e.mods.isPopupMenu()&&onEdit)onEdit();}
 void mouseDrag(const juce::MouseEvent&)override{if(copyFrom>=0)setMouseCursor(juce::MouseCursor::CopyingCursor);}
 void mouseUp(const juce::MouseEvent& e)override{if(copyFrom>=0){int target=slotAt(e.position);if(target>=0&&target!=copyFrom){if(arp)copyArpSlot(p,copyFrom,target);else copyClipSlot(p,copyFrom,target);selectSlot(target,true);}copyFrom=-1;setMouseCursor(juce::MouseCursor::PointingHandCursor);repaint();}}
 void mouseMove(const juce::MouseEvent& e)override{int slot=slotAt(e.position);if(slot<0){setTooltip(e.position.x<20?"Playback on/off":"Open sequence editor");return;}auto bank=p.sequences();auto& data=arp?bank->arps[slot]:bank->clips[slot];setTooltip(juce::String(slot+1)+" / "+data.name+(arp?" - click: select arp pattern":" - click: launch/stop clip")+"; Shift: select; right-click: edit");}
 bool keyPressed(const juce::KeyPress& key)override{int slot=juce::jlimit(0,11,(int)p.value(arp?"seqArpSlot":"seqClipSlot"));if(key==juce::KeyPress::leftKey||key==juce::KeyPress::rightKey){selectSlot((slot+(key==juce::KeyPress::leftKey?11:1))%12,true);return true;}if(key==juce::KeyPress::spaceKey){selectSlot(slot);return true;}if(key==juce::KeyPress::returnKey){if(onEdit)onEdit();return true;}return false;}
};
}
